-- Recreate the trigger function to use transaction_id instead of id
CREATE OR REPLACE FUNCTION queue_for_azure_sync()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO azure_sync_queue (
        entity_type,
        entity_id,
        payload
    ) VALUES (
        'TRANSACTION',
        NEW.transaction_id,  -- Changed from NEW.id
        jsonb_build_object(
            'transaction_id', NEW.transaction_id,
            'dispenser_address', NEW.dispenser_address,
            'volume_litres', NEW.volume_litres,
            'amount_cents', NEW.amount_cents,
            'timestamp', NEW.started_at
        )
    );
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
